
CREATE TABLE IF NOT EXISTS login_limits(key VARCHAR(64) PRIMARY KEY,attempts INTEGER NOT NULL,expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS sites(id VARCHAR(8) PRIMARY KEY,name VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS users(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username VARCHAR(80) UNIQUE NOT NULL,passhash TEXT NOT NULL,role VARCHAR(20) NOT NULL,site VARCHAR(8),active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS sessions(token_hash VARCHAR(64) PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS products(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(150) UNIQUE NOT NULL,unit VARCHAR(16) NOT NULL,reference_price NUMERIC(14,2) NOT NULL,channel VARCHAR(16) NOT NULL);
CREATE TABLE IF NOT EXISTS stock(site VARCHAR(8) NOT NULL REFERENCES sites(id),product_id INTEGER NOT NULL REFERENCES products(id),qty NUMERIC(14,3) NOT NULL DEFAULT 0,PRIMARY KEY(site,product_id));
CREATE TABLE IF NOT EXISTS orders(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,site VARCHAR(8) NOT NULL REFERENCES sites(id),product_id INTEGER NOT NULL REFERENCES products(id),qty NUMERIC(14,3) NOT NULL,unit_price NUMERIC(14,2) NOT NULL,channel VARCHAR(16) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'draft',created_by INTEGER NOT NULL REFERENCES users(id),created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS movements(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,site VARCHAR(8) NOT NULL REFERENCES sites(id),product_id INTEGER NOT NULL REFERENCES products(id),delta NUMERIC(14,3) NOT NULL,reason VARCHAR(40) NOT NULL,order_id INTEGER REFERENCES orders(id),actor INTEGER NOT NULL REFERENCES users(id),created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,site VARCHAR(8) NOT NULL REFERENCES sites(id),title VARCHAR(500) NOT NULL,assignee_role VARCHAR(20) NOT NULL,done BOOLEAN NOT NULL DEFAULT FALSE,actor INTEGER NOT NULL REFERENCES users(id),created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor INTEGER REFERENCES users(id),action VARCHAR(80) NOT NULL,detail TEXT NOT NULL,created BIGINT NOT NULL);

CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY,applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO schema_migrations(version) VALUES(1) ON CONFLICT(version) DO NOTHING;
